const effectiveSettlementPreview = { signature: "", loading: false, results: [] };

async function refreshEffectiveSettlementPreview(signature) {
  const branchId = activeOperationBranchId();
  const settlementMonth = `${state.billingMonth}-01`;
  const client = window.TennisNoteDataClient;
  const entries = operationBranchCoaches().filter((coach) => coach.serverRoleId && coach.branchId === branchId);
  effectiveSettlementPreview.signature = signature;
  effectiveSettlementPreview.loading = true;
  renderEffectiveSettlementPreview();
  const results = await Promise.all(entries.map(async (coach) => {
    try {
      if (!adminApprovalReady() || !client?.rpc) throw new Error("authentication_required");
      const scope = { branchId, coachRoleId: coach.serverRoleId, settlementMonth };
      const result = await client.rpc("tn_coach_settlement_scope_v2", {
        target_branch_id: branchId, target_coach_role_id: coach.serverRoleId, target_month: settlementMonth,
      });
      return { coach, value: window.TennisNoteSettlementAdjustment.effectiveProjection(result, scope) };
    } catch (error) {
      return { coach, error: window.TennisNoteSettlementAdjustment.effectiveError(error) };
    }
  }));
  if (effectiveSettlementPreview.signature !== signature || effectiveSettlementPreviewSignature() !== signature) return;
  effectiveSettlementPreview.results = results;
  effectiveSettlementPreview.loading = false;
  renderEffectiveSettlementPreview();
}

function effectiveSettlementPreviewSignature() {
  return JSON.stringify([activeOperationBranchId(), state.billingMonth,
    serverPaymentSyncState.lastLoadedAt, operationBranchCoaches().map((coach) => coach.serverRoleId), coachSettlementRules]);
}

if (!adminDemoMode) {
  const signature = effectiveSettlementPreviewSignature();
  if (effectiveSettlementPreview.signature !== signature) void refreshEffectiveSettlementPreview(signature);
  else renderEffectiveSettlementPreview();
  return;
}

// A payment-row total cannot stand in for lesson-month settlement. Keep the
// existing monthly preview as authority instead of a second name-based sum.
if (!adminDemoMode) return '<span class="billing-settlement-pending">월 정산에서 적용일별 계산 확인</span>';

function renderEffectiveSettlementPreview() {
  const rows = $("#coachSettlementPreviewRows");
  const summary = $("#coachSettlementSummary");
  if (!rows) return;
  const current = effectiveSettlementPreview;
  if (current.loading) {
    rows.innerHTML = '<tr><td colspan="6">적용일별 서버 계산을 확인하고 있습니다.</td></tr>';
    if (summary) summary.textContent = "정산 확인 중";
    return;
  }
  if (summary) summary.innerHTML = current.results.map((entry) => `<article>
    <span>${escapeHtml(entry.coach.name)}</span>
    <strong>${entry.error ? "확인 필요" : `${money.format(entry.value.estimatedSettlement)}원`}</strong>
    <small>${escapeHtml(entry.error || `실제 진행 ${entry.value.settledMinutes}분 · 결제 ${entry.value.paymentCount}건${entry.value.confirmationReady ? "" : " · 새 계산 미리보기 / 기존 확정 내역 유지"}`)}</small>
  </article>`).join("") || "계산할 코치가 없습니다.";
  const items = current.results.flatMap((entry) => entry.error ? [{ ...entry, row: null }]
    : entry.value.rows.map((row) => ({ ...entry, row })));
  state.settlementPage = normalizeDashboardPage(items.length, state.settlementPage, billingPageSize);
  rows.innerHTML = items.slice(state.settlementPage * billingPageSize, (state.settlementPage + 1) * billingPageSize)
    .map(({ coach, row, error }) => {
      if (error) return `<tr><td colspan="6">${escapeHtml(coach.name)} · ${escapeHtml(error)}</td></tr>`;
      const exactTicket = [...tickets, ...expiredTickets, ...(adminLiveDataState.settlementTickets || [])]
        .find((ticket) => String(ticket.serverTicketId || ticket.id) === row.ticketId);
      return `<tr><td>${escapeHtml(exactTicket?.member || "회원권 근거 확인")}</td>
        <td>${escapeHtml(coach.name)}</td><td>${money.format(row.amount)}원</td>
        <td>구매·진행 당시 근거<br><small>${Number(row.settledSessions)}회 · 실제 ${Number(row.settledMinutes)}분</small></td>
        <td>날짜별 조건 · 월 최종 반올림</td><td>${money.format(row.estimatedSettlement)}원</td></tr>`;
    }).join("") || '<tr><td colspan="6">선택한 달의 계산 근거가 없습니다.</td></tr>';
  renderDashboardPager("#coachSettlementPreviewPager", items.length, state.settlementPage, "settlement", billingPageSize);
}

(function attachTennisNoteSettlementAdjustment(global) {
  "use strict";

  function money(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
  }

  function normalized(value) {
    return String(value || "").trim().toLowerCase();
  }

  function paymentAmounts(payment = {}) {
    const grossAmount = money(payment.finalAmount ?? payment.final_amount ?? payment.amount);
    const refundedAmount = Math.min(
      grossAmount,
      money(payment.refundedAmount ?? payment.refunded_amount),
    );
    const netAmount = Math.max(0, grossAmount - refundedAmount);
    const originalSettlementBase = money(
      payment.settlementBaseAmount
        ?? payment.settlement_base_amount
        ?? payment.settlementBase
        ?? grossAmount,
    );
    const settlementBase = grossAmount > 0
      ? Math.round(originalSettlementBase * netAmount / grossAmount)
      : 0;
    return {
      grossAmount,
      refundedAmount,
      netAmount,
      originalSettlementBase,
      settlementBase,
      refundAdjusted: refundedAmount > 0,
    };
  }

  function isIncluded(payment = {}) {
    const status = normalized(payment.serverStatus || payment.status);
    const refundStatus = normalized(payment.refundStatus || payment.refund_status);
    if (["processing", "reconcile_required"].includes(refundStatus)) return false;
    const amounts = paymentAmounts(payment);
    return ["paid", "verified", "refunded"].includes(status) && amounts.netAmount > 0;
  }

  // Projection only: formulas and rounding belong to the server calculator.
  function effectiveProjection(value, scope) {
    if (!value?.ok || value.calculationVersion !== "r3_effective_settlement_v2"
      || value.scope?.branchId !== scope.branchId || value.scope?.coachRoleId !== scope.coachRoleId
      || value.scope?.settlementMonth !== scope.settlementMonth
      || !/^[0-9a-f]{64}$/.test(value.sourceFingerprint || "")
      || !Array.isArray(value.lines) || !Array.isArray(value.sourceManifest?.tickets)) {
      throw new Error("settlement_scope_or_version_mismatch");
    }
    for (const key of ["totalSettlementAmount", "revenueAmount", "settledSessions", "settledMinutes", "paymentCount"]) {
      if (!Number.isSafeInteger(value.totals?.[key]) || value.totals[key] < 0) throw new Error("settlement_total_invalid");
    }
    if (value.lines.reduce((sum, line) => sum + Number(line.settlementAmount), 0) !== value.totals.totalSettlementAmount) {
      throw new Error("settlement_line_total_mismatch");
    }
    const ticketById = new Map(value.sourceManifest.tickets.map((ticket) => [ticket.id, ticket]));
    return {
      ...value, coachRoleId: scope.coachRoleId, branchId: scope.branchId,
      confirmationReady: value.confirmationReady === true,
      month: scope.settlementMonth.slice(0, 7), ruleType: "effective_periods",
      estimatedSettlement: value.totals.totalSettlementAmount,
      revenueAmount: value.totals.revenueAmount, settledSessions: value.totals.settledSessions,
      paymentCount: value.totals.paymentCount, settledMinutes: value.totals.settledMinutes,
      rows: value.lines.map((line) => {
        const ticket = ticketById.get(line.sourceTicketId);
        if (!ticket || !Number.isSafeInteger(line.settlementAmount) || line.settlementAmount < 0) {
          throw new Error("settlement_line_scope_mismatch");
        }
        return { ticketId: ticket.id, userId: ticket.userId, coachRoleId: scope.coachRoleId,
          estimatedSettlement: line.settlementAmount, settledSessions: line.settledSessions,
          settledMinutes: line.settledMinutes, totalSessions: line.totalSessions,
          amount: line.netAmount, memberName: "회원권별 계산 근거", productName: "적용일별 정산",
          method: line.sourcePaymentId ? "결제 근거 보존" : "미입금 포함 · 시간제",
          calculationComponents: line.calculationComponents };
      }),
    };
  }

  function effectiveError(error) {
    const code = String(error?.payload?.message || error?.message || "");
    if (/lock timeout|lock_not_available|55P03/.test(code)) return "정산 근거가 변경 중입니다. 잠시 후 다시 확인해 주세요. 이번 계산은 확정하지 않았습니다.";
    if (code.includes("settlement_hold_")) return "확인 필요: 구매·수업·적용기간 또는 환불 조정 근거를 확인해 주세요. 임의 금액은 계산하지 않았습니다.";
    if (/scope|forbidden|authentication/.test(code)) return "현재 지점과 코치 권한을 다시 확인해 주세요.";
    return "정산 자료를 불러오지 못했습니다. 새로고침 후 다시 확인해 주세요.";
  }

  global.TennisNoteSettlementAdjustment = Object.freeze({
    paymentAmounts,
    isIncluded,
    effectiveProjection,
    effectiveError,
  });
})(window);

